\documentclass{article}
\usepackage{tikz}
\usetikzlibrary{shapes}

\newcommand{\drawchessboard}[1]{%
  \begin{tikzpicture}[scale=0.5]
    \foreach \x in {1,...,8} {
      \foreach \y in {1,...,8} {
        \pgfmathsetmacro{\squarecolor}{mod(\x+\y,2)==0 ? "lightgray" : "gray"}
        \fill[\squarecolor] (\x,\y) rectangle ++(1,1);
      }
    }
    \foreach \piece [count=\i] in {#1} {
      \pgfmathsetmacro{\x}{mod(\i-1,8)+1}
      \pgfmathsetmacro{\y}{int((\i-1)/8)+1}
      \node at (\x+0.5,\y+0.5) {\piece};
    }
    \draw[step=1cm,gray,thin] (1,1) grid (9,9);
  \end{tikzpicture}
}

